#!/usr/bin/env python3
"""
make-fixtures.py — build fake apps + matching traffic so the skill can be exercised offline.

Three synthetic targets, each a different real-world shape, with the ciphertext generated by the
actual algorithm so decryption really has to work:

  1. bank-static   APK, AES-256-CBC, IV prepended, key hardcoded in the DEX      (ladder rung 1)
  2. shop-cryptojs APK, CryptoJS with a STRING key -> OpenSSL "Salted__" envelope (rung 1 + the
                   passphrase trap: the literal is not the key)
  3. wallet-hybrid APK + handshake traffic, RSA-wrapped session key in a JWE-ish
                   token with no auth tag, key never in the artifact                (rung 2)

Usage (from anywhere — the script locates the skill's own scripts/ next to it):
  python3 "$SKILL"/testdata/make-fixtures.py /tmp/skilltest             # writes apps/ and traffic/
  python3 "$SKILL"/testdata/make-fixtures.py /tmp/skilltest --answers   # + ANSWERS.md (don't peek)

Then point the skill at it:  /decrypt-app-traffic /tmp/skilltest/apps
The traffic lives in /tmp/skilltest/traffic (raw HTTP messages, as if saved from a proxy).
"""

from __future__ import annotations

import argparse
import base64
import importlib.util
import json
import os
import struct
import subprocess
import sys
import zipfile

HERE = os.path.dirname(os.path.abspath(__file__))
CLI = os.path.join(HERE, "..", "scripts", "crypto-cli.py")   # sibling of this folder

BANK_KEY = "0f1e2d3c4b5a69788796a5b4c3d2e1f0"          # hex, AES-128
SHOP_PASS = "7x!A%D*G-KaPdSgV"                          # CryptoJS *passphrase*
WALLET_HDR = {"alg": "RSA-OAEP", "enc": "A256CTR"}


def cc():
    spec = importlib.util.spec_from_file_location("cc", CLI)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


# --------------------------------------------------------------------------- DEX/APK plumbing
def build_dex(strings):
    n = len(strings)
    header = bytearray(0x70)
    header[0:8] = b"dex\n035\x00"
    ids_off = 0x70
    data, offsets = b"", []
    data_off = ids_off + 4 * n
    for s in strings:
        offsets.append(data_off + len(data))
        b = s.encode()
        data += bytes([len(s) & 0x7F]) + b + b"\x00"
    struct.pack_into("<II", header, 0x38, n, ids_off)
    return bytes(header) + b"".join(struct.pack("<I", o) for o in offsets) + data


def raw_request(path, host, body, extra=()):
    headers = ["POST %s HTTP/1.1" % path, "Host: %s" % host, "Content-Type: application/json",
               "User-Agent: okhttp/4.12.0", "Content-Length: %d" % len(body)]
    headers.extend(extra)
    return "\r\n".join(headers) + "\r\n\r\n" + body


def write(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    mode = "wb" if isinstance(data, bytes) else "w"
    with open(path, mode) as fh:
        fh.write(data)


# --------------------------------------------------------------------------- the three targets
def bank_static(out, m):
    """Hardcoded AES key in the DEX; body is {"data": base64(iv|ct)}."""
    apk = os.path.join(out, "apps", "bank-static.apk")
    dex = build_dex([
        "AES/CBC/PKCS5Padding", "javax/crypto/spec/SecretKeySpec", "javax/crypto/spec/IvParameterSpec",
        BANK_KEY, "https://api.bank-static.example.com/v2/", "Lcom/example/bankstatic/net/Crypto;",
        "okhttp3/OkHttpClient", "HmacSHA256", "X-Request-Id",
    ])
    os.makedirs(os.path.dirname(apk), exist_ok=True)
    with zipfile.ZipFile(apk, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("classes.dex", dex)
        z.writestr("res/values/strings.xml",
                   b'<resources><string name="api_base">https://api.bank-static.example.com/v2/</string></resources>')
        z.writestr("lib/arm64-v8a/libapp.so", b"\x7fELF" + b"\x00" * 40 + b"EVP_aes_128_cbc\x00")

    bodies = [
        {"cpf": "12345678900", "op": "balance"},
        {"cpf": "12345678900", "op": "transfer", "to": "98765432100", "amount": 150.75},
        {"cpf": "12345678900", "op": "statement", "from": "2026-08-01", "to": "2026-08-31"},
    ]
    for i, pt in enumerate(bodies, 1):
        args = _args(m, mode="CBC", structure="iv_ct", key="hex:" + BANK_KEY)
        ct = m.do_encrypt(json.dumps(pt).encode(), args)
        body = json.dumps({"data": ct, "ts": 1767225600 + i})
        write(os.path.join(out, "traffic", "bank-static-%d.txt" % i),
              raw_request("/v2/account", "api.bank-static.example.com", body,
                          ["X-Request-Id: 3f9a1b%02d" % i]))


def shop_cryptojs(out, m):
    """CryptoJS passphrase form: the 16-char literal is a password, not a key."""
    apk = os.path.join(out, "apps", "shop-cryptojs.apk")
    js = ("""
var CryptoJS = require("crypto-js");
// the whole request body is encrypted with a literal passed as a STRING
function encryptBody(o) { return CryptoJS.AES.encrypt(JSON.stringify(o), "%s").toString(); }
function decryptBody(s) { return CryptoJS.AES.decrypt(s, "%s").toString(CryptoJS.enc.Utf8); }
fetch("https://api.shop-cryptojs.example.com/v1/checkout",
      {method: "POST", body: JSON.stringify({request: encryptBody(cart)})});
""" % (SHOP_PASS, SHOP_PASS)).encode()
    os.makedirs(os.path.dirname(apk), exist_ok=True)
    with zipfile.ZipFile(apk, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("classes.dex", build_dex(["com/facebook/react/ReactActivity", "okhttp3/OkHttpClient"]))
        z.writestr("assets/index.android.bundle", js)

    for i, pt in enumerate([
        {"items": [{"sku": "A-100", "qty": 1}], "total": 99.9, "coupon": None},
        {"items": [{"sku": "B-200", "qty": 3}], "total": 12.0, "coupon": "WELCOME10"},
        {"items": [{"sku": "A-100", "qty": 1}], "total": 99.9, "coupon": None},
    ], 1):
        args = _args(m, mode="CBC", structure="openssl", key="utf8:" + SHOP_PASS, kdf="evp-md5")
        ct = m.do_encrypt(json.dumps(pt).encode(), args)
        body = json.dumps({"request": ct})
        write(os.path.join(out, "traffic", "shop-cryptojs-%d.txt" % i),
              raw_request("/v1/checkout", "api.shop-cryptojs.example.com", body))


def wallet_hybrid(out, m):
    """Session key delivered by a handshake, wrapped to the CLIENT's public key. Not in the APK."""
    keys = os.path.join(out, "keys")
    os.makedirs(keys, exist_ok=True)
    client_priv = os.path.join(keys, "client-priv.pem")     # the app's own pair (you do NOT have this)
    client_pub = os.path.join(keys, "client-pub.pem")
    subprocess.run(["openssl", "genrsa", "-out", client_priv, "2048"], capture_output=True)
    subprocess.run(["openssl", "rsa", "-in", client_priv, "-pubout", "-out", client_pub],
                   capture_output=True)

    apk = os.path.join(out, "apps", "wallet-hybrid.apk")
    js = b"""
var forge = require("node-forge");
// a fresh keypair every session; the server returns the AES key encrypted to it
var client = forge.pki.rsa.generateKeyPair(2048);
$http.post("/api/init", {jwk: sign(sessionId) + "." + btoa(client.pub), version: "0.4"});
function onKey(r) { var jwk = JSON.parse(rsaDecrypt(client.priv, r.split(".")[0]));
                    aesKey = atob(jwk.kid); }            // 32 printable chars, used as UTF-8
function enc(o) { return hdr + ".." + b64(iv) + "." + b64(aesCtr(aesKey, iv, o)) + ". "; }
"""
    os.makedirs(os.path.dirname(apk), exist_ok=True)
    with zipfile.ZipFile(apk, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("classes.dex", build_dex(["AES/CTR/NoPadding", "RSA/ECB/OAEPWithSHA-1AndMGF1Padding",
                                             "javax/crypto/Cipher", "https://api.wallet.example.com/api/",
                                             "Lcom/example/wallet/crypto/SessionCrypto;"]))
        z.writestr("assets/www/app/js/crypto-bundle.js", js)

    session = "9c1f4e7a-2b6d-4c81-93af-5e0d7b2a1c44"
    aes_key = "K3yF0rTh1sSess10nOnly7x9QzR2mNbV"          # 32 printable chars, UTF-8 bytes
    # handshake 1: the client publishes its public key
    write(os.path.join(out, "traffic", "wallet-handshake-1.txt"),
          raw_request("/api/init", "api.wallet.example.com",
                      json.dumps({"jwk": "SIG." + base64.b64encode(open(client_pub, "rb").read()).decode(),
                                  "reset": False, "version": "0.4"}),
                      ["X-Session-Id: " + session]))
    # handshake 2: the server returns the AES key encrypted to that public key
    wrapped = m.rsa_op(json.dumps({"jwk": {"kid": base64.b64encode(aes_key.encode()).decode()},
                                   "exp": 900}).encode(),
                       "file:" + client_pub, "oaep-sha1", encrypt=True)
    write(os.path.join(out, "traffic", "wallet-handshake-2.txt"),
          "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n"
          + json.dumps(base64.b64encode(wrapped).decode() + ".SERVERSIG"))
    # three encrypted bodies under that session key
    hdr = base64.b64encode(json.dumps(WALLET_HDR).encode()).decode().rstrip("=")
    for i, pt in enumerate([
        {"action": "login", "user": "user01", "pin": "4321"},
        {"action": "transfer", "to": "0002-99887", "amount": 2500.0},
        {"action": "statement", "page": 1},
    ], 1):
        iv = bytes([i] * 16)
        ct = m.aes_transform(aes_key.encode(), iv, json.dumps(pt).encode(), "CTR", True)
        token = ".".join([hdr, "", base64.b64encode(iv).decode(), base64.b64encode(ct).decode(), " "])
        write(os.path.join(out, "traffic", "wallet-hybrid-%d.txt" % i),
              raw_request("/api/transactions", "api.wallet.example.com", json.dumps({"data": token}),
                          ["X-Session-Id: " + session]))
    return session, aes_key, client_pub


def _args(m, **kw):
    import types
    d = dict(engine="aes", mode="CBC", mode_explicit=True, structure="raw", padding="pkcs7",
             in_encoding="base64", out_encoding="base64", encoding="base64", iv=None, iv_length=None,
             tag_length=128, cfb_segment=128, key=None, cek=None, priv=None, pub=None,
             rsa_scheme="oaep-sha256", kdf="evp-md5", pbkdf2_iter=10000, key_length=None,
             jwe_state=None, jwe_header=None, jwe_encrypted_key=None, jwe_tag=None, key_log=None,
             session=None, key_log_format="auto", no_inflate=True, deflate=False, deflate_wrap="data",
             quiet=True)
    d.update(kw)
    return types.SimpleNamespace(**d)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("out", help="directory to create (apps/, traffic/, keys/)")
    ap.add_argument("--answers", action="store_true", help="also write ANSWERS.md")
    args = ap.parse_args()
    m = cc()
    out = os.path.abspath(args.out)

    bank_static(out, m)
    shop_cryptojs(out, m)
    session, aes_key, client_pub = wallet_hybrid(out, m)

    print("wrote %s" % out)
    for d in ("apps", "traffic"):
        for f in sorted(os.listdir(os.path.join(out, d))):
            print("  %s/%s" % (d, f))
    print("\nPoint the skill at it:  /decrypt-app-traffic %s/apps" % out)
    print("Traffic (raw HTTP, as if saved from the proxy): %s/traffic" % out)

    if args.answers:
        write(os.path.join(out, "ANSWERS.md"), """# Answers (don't read before testing)

| Target | Scheme | Key | Ladder rung |
|---|---|---|---|
| bank-static | AES-128-CBC, `iv_ct`, base64, body field `data` | hex `%s`, hardcoded in classes.dex | 1 — static |
| shop-cryptojs | CryptoJS passphrase → AES-256-CBC, `openssl` structure (`U2FsdGVkX1…`), field `request` | passphrase `%s` (NOT a raw key) | 1 — static, with the passphrase trap |
| wallet-hybrid | AES-256-CTR in a 5-part token, empty wrapped-key segment, blank tag, field `data` | 32-char UTF-8 session key `%s`, delivered by `/api/init` wrapped with RSA-OAEP-SHA1 to the client's public key (%s); session `%s` | 2 — swap the client public key in handshake 1, then read handshake 2 |

Expected behaviour: rungs 1 solve from `crypto-triage.py` + `crypto-cli.py solve` alone; wallet-hybrid
must NOT be solvable from the artifact, and the analyzer should point at the handshake instead.
""" % (BANK_KEY, SHOP_PASS, aes_key, os.path.basename(client_pub), session))
        print("\n(ANSWERS.md written — don't peek until after the run.)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
